// The admin's app icons and iPhone launch screens, embedded so the Worker can serve them without a
// static asset step.
//   Icons: source scripts/admin-icon.html, screenshot as square PNGs at 180, 192 and 512 px.
//   Launch screens: source scripts/admin-launch.html, screenshot at the iPhone 17 Pro (402 x 874 pt)
//   and 17 Pro Max (440 x 956 pt) sizes at 3x, giving 1206 x 2622 and 1320 x 2868 px; and at the
//   iPad sizes listed in pwa.js at 2x, upright and sideways, saved as 16-colour PNGs to stay small.
// To change one, edit its source, re-screenshot it and replace the base64 string below.

export const ICONS = {
  "apple-touch-icon.png": "",
  "icon-192.png": "",
  "icon-512.png": "",
  "launch-1206x2622.png": "",
  "launch-1320x2868.png": "",
  "launch-1488x2266.png": "",
  "launch-1640x2360.png": "",
  "launch-1668x2388.png": "",
  "launch-1668x2420.png": "",
  "launch-2048x2732.png": "",
  "launch-2064x2752.png": "",
  "launch-2266x1488.png": "",
  "launch-2360x1640.png": "",
  "launch-2388x1668.png": "",
  "launch-2420x1668.png": "",
  "launch-2732x2048.png": "",
  "launch-2752x2064.png": "",
};

/** The PNG bytes for an icon name, or null if there is no such icon. */
export function iconBytes(name) {
  const encoded = Object.hasOwn(ICONS, name) ? ICONS[name] : null;
  if (!encoded) return null;
  return Uint8Array.from(atob(encoded), (char) => char.charCodeAt(0));
}
